pub(super) fn exercise(store:&store::ConfigStore<State,Mutation>,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){let checkpoint_id=store.parts_ref().log.current_checkpoint_id.as_deref().unwrap();let checkpoint=store.parts_ref().log.envelope.vcs.checkpoints.iter().find(|row|row.id==checkpoint_id).unwrap();let mut pins=None;turn(caller,decoder,TURN,|cx|{let text=["energy-child","s.energy.model","1","*","ck-child"];let capacity=size_of::<store::os_vcs::CompositionPin>()+text.iter().map(|text|text.len()).sum::<usize>();let d=OriginalConstructionDemand{items:1,copy_bytes:2*size_of::<store::os_vcs::CompositionPin>()+128,capacity_bytes:capacity,release_bytes:0,depth:1};admit_original_construction(cx,&mut pins,d,|_|Ok((vec![store::os_vcs::CompositionPin{child_ref:semio_framework_artifact_reference::ArtifactRef{artifact_id:text[0].into(),dialect:semio_framework_artifact_reference::ArtifactDialect{artifact_kind:text[1].into(),standard:text[2].into(),subset:text[3].into()}},checkpoint_id:text[4].into()}],RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:capacity,..Default::default()})))?;Ok(())});let pins=pins.unwrap();let input=OriginalCheckpointIdentityInput{generation:store.generation(),checkpoint,changes:&store.parts_ref().log.envelope.vcs.changes,pins:&pins};let mut hash=OriginalCheckpointIdentity::default();for index in 0..262144{if hash.digest().is_some(){break}turn(caller,decoder,TURN,|cx|{let d=hash.demands();let grant=cx.retained_grant();let mut output=None;admit_original_construction(cx,&mut output,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|Ok(((),hash.advance(&input,grant)?)))?;Ok(())});assert!(index<262143);}let digest=hash.digest().unwrap();let mut pinned=None;turn(caller,decoder,TURN,|cx|{let d=OriginalConstructionDemand{items:1,copy_bytes:size_of::<String>()+19,capacity_bytes:19,release_bytes:0,depth:1};admit_original_construction(cx,&mut pinned,d,|_|{let mut text=String::new();text.try_reserve_exact(19).unwrap();text.push_str("ck-");const HEX:&[u8;16]=b"0123456789abcdef";for byte in &digest[..8]{text.push(HEX[(byte>>4)as usize]as char);text.push(HEX[(byte&15)as usize]as char);}Ok((text,RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:19,..Default::default()}))})?;Ok(())});turn(caller,decoder,TURN,|cx|cx.with_original_retirement(|cx|{let d=hash.close_demands();close_original_retained_step(cx,d,|grant|Ok(RetainedCloneStep::Complete(hash.close_step(grant))))?;Ok(())}));let pinned=pinned.unwrap();let fields=OriginalCompositionPinFields::new(&pins);let view=store::os_spr::HistoryTransitionRepinView{checkpoint_id,pinned_checkpoint_id:&pinned,pins:&fields};let generation=store.generation();let revision=store.content_revision();let count=store.parts_ref().log.envelope.transitions.len();for cut in [0,1,8,32,64,128,usize::MAX]{let mut owner=None;let d=Source::birth_demands();assert!(d.copy_bytes<=32768&&d.capacity_bytes<=16<<20);let birth=RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.max(TURN.maximum_copy_bytes),maximum_capacity_bytes:d.capacity_bytes.max(TURN.maximum_capacity_bytes),..TURN};turn(caller,decoder,birth,|cx|{assert!(Source::admit_repin(store,&view,cx,&mut owner)?);Ok(())});let source=owner.as_mut().unwrap();let foreign=store::os_spr::HistoryTransitionRepinView{pinned_checkpoint_id:"foreign",..view};turn(caller,decoder,TURN,|cx|{assert!(source.advance_repin(store,&foreign,cx).is_err());Ok(())});let mut ready=false;for index in 0..262144{if index==cut{break}ready=turn(caller,decoder,TURN,|cx|source.advance_repin(store,&view,cx));assert_eq!(store.generation(),generation);assert_eq!(store.content_revision(),revision);assert_eq!(store.parts_ref().log.envelope.transitions.len(),count);if ready{break}assert!(index<262143);}if cut==usize::MAX{assert!(ready);let mut output=None;turn(caller,decoder,TURN,|cx|{assert!(source.take(cx,&mut output)?);Ok(())});let output=output.unwrap();assert_eq!(output.envelopes.len(),1);assert!(output.branch.is_none());assert!(!output.applies_to_head);assert_eq!(output.envelopes[0].dependencies,[store.parts_ref().log.envelope.transitions.get(0).unwrap().mutation_id.clone()]);let decoded=store::os_spr::history_transition_from_envelope(&output.envelopes[0]).unwrap().unwrap();let store::os_spr::HistoryTransition::Repin{checkpoint_id:old,pinned_checkpoint_id:new,pins:decoded_pins}=&decoded else{panic!("native pin batch preserves its canonical event")};assert_eq!(old,checkpoint_id);assert_eq!(new,&pinned);assert_eq!(decoded_pins[0].child_uri,"energy-child!s.energy.model@1/*");assert_eq!(decoded_pins[0].checkpoint_id,"ck-child");publication::close_typed(decoded,caller,decoder);publication::close_typed(output,caller,decoder);}for index in 0..262144{if source.terminal_is_empty(){break}let d=source.close_demands(4096).unwrap();let closing=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};turn(caller,decoder,closing,|cx|cx.with_original_retirement(|cx|source.close_step(cx)));assert!(index<262143);}assert!(source.terminal_is_empty());turn(caller,decoder,TURN,|cx|cx.with_original_retirement(|cx|{let d=RetirementDemand{copy_bytes:size_of::<Option<Box<Source>>>(),release_bytes:size_of::<Source>(),depth:1,..Default::default()};close_original_retained_step(cx,d,|_|{drop(owner.take());Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))})?;Ok(())}));}publication::close_typed(pinned,caller,decoder);publication::close_typed(pins,caller,decoder);}
